// =====================================================================================================
// FILE: Maroos.Web/Components/Account/IdentityRedirectManager.cs
// ORIGIN: generated by the Blazor Identity template; Maroos uses it unchanged.
// PURPOSE: Safe redirects for the account pages, optionally carrying a one-off status message
//   ("Your password has been changed.") that the next page shows with StatusMessage.razor.
// HOW THE MESSAGE TRAVELS: it's put in a short-lived cookie (5 seconds, HttpOnly, SameSite=Strict), because a
//   redirect can't carry page state. The next page reads the cookie and deletes it.
// =====================================================================================================

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Identity;
using Maroos.Web.Data;

namespace Maroos.Web.Components.Account;

internal sealed class IdentityRedirectManager(NavigationManager navigationManager)
{
    // StatusCookieName: the cookie that carries the message to the next page.
    public const string StatusCookieName = "Identity.StatusMessage";

    // StatusCookieBuilder: the cookie's settings. HttpOnly: scripts can't read it. IsEssential: it's set even
    // before cookie consent, because the page can't work without it. MaxAge: gone after 5 seconds.
    private static readonly CookieBuilder StatusCookieBuilder = new()
    {
        SameSite = SameSiteMode.Strict,
        HttpOnly = true,
        IsEssential = true,
        MaxAge = TimeSpan.FromSeconds(5),
    };

    // RedirectTo: go to an address inside this site. Anything absolute or starting with "//" (which browsers
    // treat as another site) is turned back into a path on this site: no "open redirect" to phishing pages.
    public void RedirectTo(string? uri)
    {
        uri ??= "";

        // Prevent open redirects.
        if (!Uri.IsWellFormedUriString(uri, UriKind.Relative)
            || uri.StartsWith("//", StringComparison.Ordinal))
        {
            uri = navigationManager.ToBaseRelativePath(uri);
        }

        navigationManager.NavigateTo(uri);
    }

    // RedirectTo with query values, e.g. RedirectTo("Account/RegisterConfirmation", new() { ["email"] = email }).
    public void RedirectTo(string uri, Dictionary<string, object?> queryParameters)
    {
        var uriWithoutQuery = navigationManager.ToAbsoluteUri(uri).GetLeftPart(UriPartial.Path);
        var newUri = navigationManager.GetUriWithQueryParameters(uriWithoutQuery, queryParameters);
        RedirectTo(newUri);
    }

    // RedirectToWithStatus: set the message cookie, then redirect.
    public void RedirectToWithStatus(string uri, string message, HttpContext context)
    {
        context.Response.Cookies.Append(StatusCookieName, message, StatusCookieBuilder.Build(context));
        RedirectTo(uri);
    }

    // CurrentPath: this page's address without its query string.
    private string CurrentPath => navigationManager.ToAbsoluteUri(navigationManager.Uri).GetLeftPart(UriPartial.Path);

    // RedirectToCurrentPage: reload this page (e.g. after saving a form).
    public void RedirectToCurrentPage() => RedirectTo(CurrentPath);

    public void RedirectToCurrentPageWithStatus(string message, HttpContext context)
        => RedirectToWithStatus(CurrentPath, message, context);

    // RedirectToInvalidUser: the login cookie points at an account that no longer exists: show the InvalidUser page.
    public void RedirectToInvalidUser(UserManager<ApplicationUser> userManager, HttpContext context)
        => RedirectToWithStatus("Account/InvalidUser", $"Error: Unable to load user with ID '{userManager.GetUserId(context.User)}'.", context);
}
